"""Append evidence-led contractor due diligence to the existing review."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parent
D=json.loads((R/'responsibility-review.json').read_text())
e=lambda s:html.escape(str(s),quote=True)
intro='내 집을 맡기는 기준으로 보면, 지금 가장 먼저 실제 현장을 검증할 곳은 하백/이아컴퍼니와 GAU다. 두 곳은 다른 설계자의 RC 주택을 여러 차례 완성했고, 일부 현장의 건축·설비·전기·인테리어 책임 범위도 공개했다. 포엠은 상세 확인으로 비교 대상으로 올렸다. 아직 어느 곳도 현재 배정 소장과 장기간 거주 후 상태까지 확인한 계약 확정 후보는 아니다.'
sections=[
('하백: 반복 팀의 근거가 가장 구체적이다','솔비나무집·재재소소·연안재·어흥어음은 각각 에이루트·지랩·이성범·건축사사무소 오의 RC 프로젝트다. 네 현장 모두 현우건설·양지설비·에이앤디브릭을 협력사로 올렸다. 서로 다른 설계자를 상대로 반복해서 공사를 수행한 조직이라는 판단을 뒷받침한다. 다만 협력사 이름만으로 담당 공종, 작업반, 숙련공의 동일성은 알 수 없다. 솔비·재재소소는 창호와 실내까지 도급 표기가 있지만 연안재·어흥어음은 건축만 표기한다. 이 차이는 실제 계약의 별도발주 때문인지 간략 기재인지 확인해야 한다.','이번 현장에는 어느 소장이 상주하며 공통 협력사 중 누가 다시 들어오는가? 솔비나무집의 낮은 마당과 큰 창 하부, 석재·벽돌 접합부의 시공 중 사진 및 최근 상태를 볼 수 있는가? 설계자의 마감 의도를 실제로 구현한 공종별 담당자를 확인한다.'),
('GAU: 오래된 실적과 넓은 도급 범위가 강점이다','세거리집(2018)·오라동 현이네(2021)·Ara_Owall House(2022)·HOMI(2023)의 RC 구조와 도급범위를 상세 확인했다. 단일 유명 작품에만 의존하지 않는다. HOMI는 조경까지 포함하고, Ara_Owall은 통신·인테리어까지 표기한다. 설계 이해와 토목·건축의 연계라는 회사 설명을 검증할 사례가 있다. 협력사는 프로젝트마다 다르므로 회사 이름이 같다는 이유로 호미의 결과가 재현된다고 가정하지 않는다. 100여 채 시공이라는 소개는 회사 주장으로 남겨둔다.','HOMI의 석재·창호·조경 담당사와 현재 배정팀을 연결해 달라고 한다. 오래된 세거리집이나 오라동 현이네의 건축주 동의를 받아 최근 누수·균열·창호 조정·보수 응답 기록을 확인할 가치가 크다. 준공 연도가 오래됐다는 사실 자체를 내구성 검증으로 쓰지 않는다.'),
('포엠: 이전 보류 판단은 수정하되 과대평가하지 않는다','필하우스는 시유재 고성천 설계의 RC 3층 508.96㎡ 주택으로 상세 확인됐다. 공사 기간은 2023.11.20–2024.09.30, 준공 표기는 2024.10.04다. 중도 장미량의 JS빌딩(근생)과 두성전력·화인종합설비·창작시스템이 반복된다. 주택과 비주택에서 RC 공사를 수행한 비교 후보라는 근거다. 두 작품 모두 도급범위가 공란이며, 협회 회사 페이지의 6개 작품 중 주택 분류는 필하우스 1건이다.','필하우스의 정면 준공 사진을 직접 보면 필로티와 다층 창 배열, 벽돌 타일 외장이 보인다. 건물 규모는 크지만 우리 단층 주택의 긴 스팬·석재 고정·큰 창 접합부 품질을 입증하는 사진은 아니다. 실제 계약 범위와 추가 개인주택을 확인해야 하백·GAU 수준으로 비교할 수 있다.'),
('시스홈: 제주 이력은 강화됐지만 지역팀 확인은 남는다','산방풍경은 더함건축사사무소 조한준 설계의 제주 화순리 목구조 2층 145.49㎡ 주택이다. 2018.11.27 준공과 건축·기계·전기·인테리어 도급을 확인했다. 기존의 2025년 이어서와 시차를 둔 제주 실적으로 볼 근거가 늘었다. 하지만 동일 소장·제주 상주팀의 연속성은 확인되지 않았다. 장락재도 RC/목구조 복합 주택 상세는 확인했으나 주소가 세하동뿐이어서 제주 실적으로 합산하지 않았다.','현재 RC 도서를 유지한 견적을 낼 수 있는 제주 소장과 골조팀이 필요한 비교다. 제3자 기업 DB의 행정처분 표기는 공식 원문·법인 동일성·효력 확인이 되지 않았으므로 확정 사실로 단정하지 않는다. 공개 검색에서 추가 결과가 없었다는 이유로 문제가 없다고 결론내리지도 않는다.'),
('나머지 후보: 어떤 증거가 부족한지에 따라 구분한다','JEJUPH는 외피 시험 수치라는 차별점이 있으나 그 프로젝트의 시공팀과 이번 배정팀을 연결해야 한다. 이음은 구억리·하례리 RC 실적의 외부 설계자 확인과 계약 법인·공종 범위가 우선이다. 브라운트리·JD는 청수리·제라의 공동 시공 역할을 분리하고, 위미리·명도암은 자체 목록에서 실제 도서·담당팀으로 넘어가야 한다. 엘비탑·오름은 현재 계약 주체와 반복 준공작이 더 필요하다. 다봄은 9월 15일 RC 2건을 추가 확인했으며, 현재 법인 연결과 소원재 공정·보수 경위 확인이 남았다. 화미·TCM은 포트폴리오와 별개로 제주 상주 관리·보수 체계가 관건이다.','신규 단서인 동성개발의 달 가든하우스 안성은 전원주택라이프 영상 검색 설명에서 시유재 설계·동성개발 시공을 찾았다. 다만 시행·분양도 하는 업체이므로 타인 설계의 개별 도급을 실제 받는지, 현 법인이 동일한지, 공사 범위를 확인하지 못했다. 공식 사이트 본문과 영상 본편을 검증하지 못해 추천군에는 넣지 않았다. 분양 홍보·같은 단지의 여러 동을 독립 주택 포트폴리오로 부풀리지 않는다.'),
('현재 설계와 연결해 실제로 받아야 할 증거','현재 검토 기준은 RC 본체, 박공지붕 자연 배수, 석재 외장, 큰 창과 테라스, 외부 레벨·배수, 공용부 천장 계획이다. 옛 HTML의 도면은 이 기준이 아니다. 업체가 설계를 이해하는지 보려면 최신 도서의 해당 접합부를 짚어 골조부터 마감까지 누가 책임지는지 설명하게 해야 한다. 단열재나 창호의 상품명만 제출하는 것으로 끝낼 문제가 아니다.','창 하부·테라스 문턱·석재 배면·지붕 끝·배수 최종 방류부의 실제 시공 사례와 공사 중 사진을 요구한다. 같은 현장의 도면·사진·검측·시험 기록이 연결돼야 한다. 평천장 높이와 긴 스팬은 구조 및 설비 도서와 함께 검토하고, 정확한 치수는 최신 PDF 확인 전 확정하지 않는다.'),
('내가 계약을 결정할 때 남겨둘 조건','하백과 GAU는 우선 현장검증 대상으로, JEJUPH는 성능 비교 대상으로, 포엠과 이음은 RC 추가 비교 대상으로 본다. 첫 미팅에서 과거 포트폴리오와 이번 팀의 연결을 확인하고, 건축주 동의하에 최근 진행 현장 및 2년 이상 사용한 주택의 상태를 함께 보는 순서가 합리적이다. 공개자료만으로 어느 업체든 하자 없이 믿고 맡길 수 있다고 단정할 근거는 아직 없다.','계약 전 판단을 바꿀 자료는 실제 배정 소장·동시 관리 현장 수, 공종별 책임 범위, 보수 접수와 완료 이력, 설계자 평가, 현재 공적 등록과 보증 자료다. 견적은 같은 도서·내역·제외공사로 비교해야 한다. 사진 취향이나 소개 경로가 이 증거를 대신하지 않게 한다.')]
heads=['시공사','준공작','설계','구조·연면적','준공 표기','도급범위','협력사']
md=['# 제주 시공사 심층 검증 — 실제 공사 책임과 반복 팀','','검토일: '+D['checked'],'',intro,'','## 확인한 프로젝트 11건','',D['method'],'','| '+' | '.join(heads)+' |','|'+'---|'*len(heads)]
h='<section id="responsibility"><p class="eyebrow">ACTUAL SCOPE · REPEATED TEAMS</p><h2>내 집을 맡기는 기준으로 다시 판단</h2><p class="verdict">'+e(intro)+'</p><p>'+e(D['method'])+'</p><p><a href="DUE-DILIGENCE.md">심층 검증 문서</a></p><div class="table-wrap"><table><thead><tr>'+''.join('<th>'+e(t)+'</th>' for t in heads)+'</tr></thead><tbody>'
for p in D['projects']:
 u='https://www.masterbuilder.kr/portfolio/'+p['slug']; cells=[p[k] for k in ['contractor','name','architect','structure_area','completion','scope','partners']]
 md+=['| '+' | '.join([cells[0],'['+cells[1]+']('+u+')']+cells[2:])+' |']
 h+='<tr>'+''.join('<td>'+('<a href="'+e(u)+'" target="_blank" rel="noopener noreferrer">'+e(v)+'</a>' if i==1 else e(v))+'</td>' for i,v in enumerate(cells))+'</tr>'
h+='</tbody></table></div>'
for title,body,ask in sections:
 md+=['','## '+title,'',body,'',ask]
 h+='<h3>'+e(title)+'</h3><p>'+e(body)+'</p><p>'+e(ask)+'</p>'
notes='협회 포트폴리오는 공적 사용승인 자료가 아니다. 세거리집 공사 종료일에는 2018.11.138이라는 오기가 있어 종료일을 계산하지 않았고 별도 준공일 필드만 옮겼다. 산방풍경 주소의 언덕면 표기는 원문 오기 가능성이 있어 화순리까지만 사용했다. 재재소소 6개동·어흥어음 3개동은 각각 한 프로젝트로 셌다. 협력사의 이름이 같아도 같은 법인·작업반·현재 배정이 보장되지는 않는다. 입주자 직접 인터뷰, 현장 방문, 업체 연락, 도면 전달은 하지 않았다.'
md+=['','## 오기·접근 한계·검증 경계','',notes,'','브라운트리 공식 페이지는 브라우저 인증서 오류로 상세 열람하지 못했다. 동성개발·시유재 공식 사이트 본문도 확보하지 못했다. 네이버·협회·설계자·시공사 공개자료의 기존 조사와 이번 상세 열람을 합쳤지만 모든 웹페이지를 열람했다는 뜻은 아니다. 부정적 후기 검색의 무결과는 무하자·무분쟁 증거가 아니다.','', '## 추가 출처','']
sources=[('하백 회사 페이지','https://www.masterbuilder.kr/contractor/ju-habaegjonghabgeonseol'),('GAU 회사 페이지','https://www.masterbuilder.kr/contractor/ju-jieiyuakipaegtori'),('포엠 회사 페이지','https://www.masterbuilder.kr/contractor/ju-poem'),('시스홈 회사 페이지','https://www.masterbuilder.kr/contractor/ju-siseuhomjonghabgeonseol'),('장락재 — 제주 여부 미확인','https://www.masterbuilder.kr/portfolio/jangragjae'),('달 가든하우스 안성 — 전원주택라이프 영상 검색 설명만 확인','https://www.youtube.com/watch?v=A42Fr8Zcgzs')]
h+='<h3>확인 한계와 원문</h3><p>'+e(notes)+'</p><ul>'
for t,u in sources:
 md+=['- ['+t+']('+u+') · 게시일 미확인 · 2026-09-09 조회']
 h+='<li><a href="'+e(u)+'" target="_blank" rel="noopener noreferrer">'+e(t)+'</a></li>'
h+='</ul><p class="small">이번에 필하우스 정면 외관 1장을 화면에서 추가 검토했다. 아래 갤러리 수와 별도이며 원본을 복제하지 않았다. 영상 본편은 시청하지 않았다.</p></section>'
(R/'DUE-DILIGENCE.md').write_text('\n'.join(md)+'\n')
p=R/'review.html';s=p.read_text();s=s.replace('</main>',h+'</main>');s=s.replace('<main>','<main><div class="notice"><a href="#responsibility">최신 심층 검증: 11개 현장의 도급범위·반복 협력사와 변경된 판단</a></div>',1);p.write_text(s)
p=R/'DETAIL-REVIEW.md';p.write_text(p.read_text()+'\n\n최신 책임 범위·반복 협력사 검증은 [DUE-DILIGENCE.md](DUE-DILIGENCE.md)를 함께 참조한다.\n')
print('Built responsibility review: 11 project records.')
